    func testTimelineShape() {
        for c in cases {
            let clock = BreathClock(c.config)
            XCTAssertEqual(clock.cycleSeconds, c.cycleSeconds, accuracy: tolerance, c.config.id)
            XCTAssertEqual(clock.frameCount, c.frameCount, c.config.id)
            XCTAssertEqual(clock.phases.map(\.phase), c.phases,
                           "\(c.config.id): a zero-length phase must be dropped, not kept")
        }
    }

    func testMatchesReferenceEngine() {
        var compared = 0
        for c in cases {
            let clock = BreathClock(c.config)
            for (t, cycle, phase, progress, phaseProgress, holdPulse) in c.samples {
                let s = clock.at(t)
                XCTAssertEqual(s.cycle, cycle, "\(c.config.id) cycle at t=\(t)")
                XCTAssertEqual(s.phase, phase, "\(c.config.id) phase at t=\(t)")
                XCTAssertEqual(s.progress, progress, accuracy: tolerance,
                               "\(c.config.id) progress at t=\(t)")
                XCTAssertEqual(s.phaseProgress, phaseProgress, accuracy: tolerance,
                               "\(c.config.id) phaseProgress at t=\(t)")
                XCTAssertEqual(s.holdPulse, holdPulse, accuracy: tolerance,
                               "\(c.config.id) holdPulse at t=\(t)")
                compared += 1
            }
        }
        XCTAssertEqual(compared, 162,
                       "every sample in the fixture must actually be compared")
    }

    /// A hold is flat by definition. If it eased, the joins either side of it
    /// would carry a step — which is the whole reason holds are declared rather
    /// than interpolated.
    func testHoldsAreFlat() {
        for c in cases {
            let clock = BreathClock(c.config)
            for span in clock.phases where span.phase.isHold {
                let expected: Double = span.phase == .holdAfterInhale ? 1 : 0
                for i in 0...20 {
                    let t = span.start + span.seconds * Double(i) / 20.0
                    XCTAssertEqual(clock.at(t).progress, expected, accuracy: tolerance,
                                   "\(c.config.id) \(span.phase) at \(t)")
                }
            }
        }
    }

    /// Every phase is a whole number of frames. 0.45 s is 13.5 of them, and a
    /// rounded boundary against an engine sampling exact seconds cost a 7%
    /// disagreement on a seven-frame phase.
    func testPhasesAreWholeFrames() {
        for c in cases {
            for span in BreathClock(c.config).phases {
                let frames = span.seconds * Double(BreathClock.fps)
                XCTAssertEqual(frames, frames.rounded(), accuracy: 1e-9,
                               "\(c.config.id) \(span.phase) is \(frames) frames")
            }
        }
    }
}
